import numpy as np
def _fixture(scale=0.08, n=12):
    j=np.arange(n,dtype=float); z=1-2*(j+.5)/n; r=np.sqrt(1-z*z); a=2*np.pi*j/((1+np.sqrt(5))/2)
    u=np.column_stack((r*np.cos(a),r*np.sin(a),z)); u/=np.linalg.norm(u,axis=1,keepdims=True)
    w=np.full(n,4*np.pi/n)
    ref=np.arange(27,dtype=float).reshape(3,3,3)/31-.35; ref=.5*(ref+ref.swapaxes(1,2)); ref[0,0,0]+=1.2; ref[1,1,1]-=.8; ref[2,2,2]+=.55
    mode=np.sin(np.arange(27,dtype=float)+.3).reshape(3,3,3); mode=.5*(mode+mode.swapaxes(1,2)); mode/=np.linalg.norm(mode)
    basis=(1+.035)*ref+scale*mode
    return basis,ref,u,w
def _flat(value):
    pieces=[]
    for item in value if isinstance(value,tuple) else (value,): pieces.extend(np.asarray(item,dtype=float).ravel().tolist())
    return np.asarray(pieces,dtype=float)
def _value_error(function,*args):
    try: function(*args)
    except ValueError: return 1.0
    return 0.0

